// QA-06 Build Panel Page — outputs { page_html }. Token gates access via ?token=.
const SYNC_TOKEN = '0211fb62410106c2d4884f3131fd219390ded7d87a8f46e2';
const query = $json.query || {};
const token = query.token || '';
const authed = token === SYNC_TOKEN;

const CATALOG = [
  { g: 'A · Funnel', items: [ ['E2E-02', 'CTA interés → sin abrir precios'] ] },
  { g: 'B · Pricing / ventana', items: [ ['E2E-04', '¿cuánto cuesta? → QUOTED'], ['E2E-05', 'Botón plan → PLAN_SELECTED'], ['E2E-06', 'Selección de plan por texto → PLAN_SELECTED'], ['PRC-01', 'CTA inicial afirmativo → SIN precios'], ['PRC-02', 'FAQ informativa → SIN precios'], ['PRC-03', 'Pedido explícito de precio → QUOTED'], ['PRC-05', 'ya cotizado + neutro → no re-cotiza a la fuerza'], ['PRC-06', 'mensaje neutro no fuerza QUOTED'], ['WIN-12', 'Selección plan 12m → PLAN_SELECTED'], ['WIN-CHG', 'Cambio de plan (36m→24m) re-seleccionable, no cierra'] ] },
  { g: 'C · Botones / guardas', items: [ ['BTN-01', 'revisar_otro_plan NO cierra (no WON)'], ['BTN-03', 'tengo_una_duda no cierra ni pierde'], ['INT-01', 'Botón interés (si_quiero_saber_mas) → engancha sin precios'], ['TOP-01', 'Botón gancho (gancho_q2_planes) → no fuerza cotización'], ['GRD-02', 'revisar_otro_plan @ENGAGED (sin plan) → sin transición ile'], ['VEH-01', 'auto_kia @CONTACTED_1 → sin cierre ni precios'], ['VEH-02', 'flota @CONTACTED_1 → manejado sin estado ilegal'], ['VEH-03', 'moto (out-of-scope) @CONTACTED_1 → sin crash ni cierre'] ] },
  { g: 'D · Handoff / terminales', items: [ ['E2E-05N', 'Handoff → nota privada de operador con vehículo'], ['E2E-07', 'Confirma contratar → HANDOFF_HUMAN'], ['HDF-01', 'sin señal → NO handoff (authority F2)'], ['HDF-02', 'WON + inbound → estado intacto'], ['HDF-03', 'HANDOFF_HUMAN + inbound → estado intacto'], ['PROP-01', 'Botón enviar_propuesta → no cierra ni pierde'], ['HDF-04', 'Botón contactar_a_un_asesor @QUOTED → HANDOFF_HUMAN'], ['GRD-01', 'si_quiero_contratar @QUOTED (sin plan) → NO handoff'], ['GRD-03', 'enviar_propuesta @QUOTED (sin plan) → NO handoff ni cierre'] ] },
  { g: 'E · Pérdida', items: [ ['LOSS-01', 'no me interesa → pérdida'], ['LOSS-02', 'no, sí quiero (ambiguo) → NO pierde'] ] },
  { g: 'F · Negativos / infra', items: [ ['NEG-02', 'mensaje solo emoji → sin crash ni cierre'], ['NEG-03', 'prompt injection → sin cierre ni plan'], ['INF-01', 'contenido mínimo (whitespace) → sin crash ni cierre'], ['INF-02', 'payload de botón desconocido → UNKNOWN_BUTTON sin transici'], ['INF-03', 'mensaje muy largo → sin crash'] ] },
  { g: 'G · Outbound follow-up (manual)', items: [ ['OUT-FU-01', 'CONTACTED_1 → CONTACTED_3 con WhatsApp real', true] ] },
];

if (!authed) {
  return [{ json: { page_html: '<!doctype html><meta charset=utf-8><title>QA Panel</title><body style="font-family:system-ui;background:#0f1115;color:#e6e6e6;display:grid;place-items:center;height:100vh;margin:0"><div style="text-align:center"><h1>🔒 QA Panel CRIS</h1><p>Acceso restringido. Añade <code>?token=…</code> a la URL.</p></div></body>' } }];
}

const catHtml = CATALOG.map(sec => {
  const rows = sec.items.map(([id, t, manual]) =>
    `<label class="sc${manual ? ' manual' : ''}"><input type="checkbox" class="scbox" value="${id}" data-manual="${manual ? '1' : '0'}"><span class="scid">${id}</span><span class="sct">${t}${manual ? ' · manual' : ''}</span></label>`
  ).join('');
  return `<div class="grp"><div class="grph"><label class="gsel"><input type="checkbox" class="gbox"><b>${sec.g}</b></label><span class="gcount">${sec.items.length}</span></div><div class="grpb">${rows}</div></div>`;
}).join('');

const html = `<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QA · E2E CRIS</title><style>
:root{--bg:#0f1115;--panel:#171a21;--panel2:#1e222b;--bd:#2a2f3a;--tx:#e7eaf0;--mut:#9aa3b2;--acc:#5b8cff;--ok:#2ecc71;--fail:#ff5c6c;--warn:#f5b942;--run:#5b8cff}
*{box-sizing:border-box}body{margin:0;font-family:system-ui,-apple-system,Segoe UI,Roboto,sans-serif;background:var(--bg);color:var(--tx);font-size:14px}
a{color:var(--acc)}code{font-family:ui-monospace,Menlo,monospace;font-size:.85em}
header{padding:14px 20px;border-bottom:1px solid var(--bd);display:flex;align-items:center;gap:16px;flex-wrap:wrap;background:linear-gradient(180deg,#181c24,#12151b)}
header h1{font-size:16px;margin:0;font-weight:700;letter-spacing:.2px}
.health{display:flex;gap:10px;flex-wrap:wrap;margin-left:auto;font-size:12px}
.pill{padding:4px 10px;border-radius:999px;background:var(--panel2);border:1px solid var(--bd);display:flex;gap:6px;align-items:center}
.dot{width:8px;height:8px;border-radius:50%;background:var(--mut)}.dot.ok{background:var(--ok)}.dot.bad{background:var(--fail)}.dot.warn{background:var(--warn)}
nav{display:flex;gap:2px;padding:0 16px;border-bottom:1px solid var(--bd);background:var(--panel)}
nav button{background:none;border:none;color:var(--mut);padding:12px 16px;cursor:pointer;font-size:13px;border-bottom:2px solid transparent}
nav button.on{color:var(--tx);border-bottom-color:var(--acc)}
main{padding:20px;max-width:1100px;margin:0 auto}
.card{background:var(--panel);border:1px solid var(--bd);border-radius:12px;padding:16px;margin-bottom:16px}
.row{display:flex;gap:12px;flex-wrap:wrap;align-items:center}
.presets{display:grid;grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px;margin-bottom:8px}
.preset{background:var(--panel2);border:1px solid var(--bd);border-radius:10px;padding:12px;cursor:pointer;text-align:left}
.preset:hover{border-color:var(--acc)}.preset b{display:block;margin-bottom:4px}.preset small{color:var(--mut)}
.grp{border:1px solid var(--bd);border-radius:10px;margin-bottom:8px;overflow:hidden}
.grph{display:flex;align-items:center;justify-content:space-between;padding:8px 12px;background:var(--panel2)}
.gsel{display:flex;gap:8px;align-items:center;cursor:pointer}.gcount{color:var(--mut);font-size:12px}
.grpb{display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:2px;padding:6px}
.sc{display:flex;gap:8px;align-items:center;padding:6px 8px;border-radius:6px;cursor:pointer}.sc:hover{background:var(--panel2)}.sc.manual{border:1px solid #5f4630;background:#1f1a14}.sc.manual .scid{color:#ffd49a}
.scid{font-family:ui-monospace,monospace;font-size:11px;color:var(--acc);min-width:62px}.sct{color:var(--mut);font-size:12px}
select,input[type=text]{background:var(--panel2);border:1px solid var(--bd);color:var(--tx);border-radius:8px;padding:8px 10px;font-size:13px}
button.btn{background:var(--acc);border:none;color:#fff;padding:9px 16px;border-radius:8px;cursor:pointer;font-weight:600;font-size:13px}
button.btn:hover{filter:brightness(1.1)}button.btn.sec{background:var(--panel2);border:1px solid var(--bd);color:var(--tx)}
button.btn:disabled{opacity:.5;cursor:not-allowed}
table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:8px 10px;border-bottom:1px solid var(--bd)}th{color:var(--mut);font-weight:600}
.badge{padding:2px 8px;border-radius:999px;font-size:11px;font-weight:600}
.b-ok{background:rgba(46,204,113,.15);color:var(--ok)}.b-fail{background:rgba(255,92,108,.15);color:var(--fail)}.b-run{background:rgba(91,140,255,.15);color:var(--run)}.b-mut{background:var(--panel2);color:var(--mut)}
.mono{font-family:ui-monospace,monospace;font-size:12px}.mut{color:var(--mut)}
.hidden{display:none}.progress{height:6px;background:var(--panel2);border-radius:999px;overflow:hidden;margin:10px 0}.bar{height:100%;background:var(--acc);width:0;transition:width .3s}
details{background:var(--panel2);border:1px solid var(--bd);border-radius:8px;padding:8px 12px;margin:6px 0}summary{cursor:pointer}
pre{background:#0c0e13;border:1px solid var(--bd);border-radius:8px;padding:10px;overflow-x:auto;font-size:11px}
.toast{position:fixed;bottom:20px;right:20px;background:var(--panel2);border:1px solid var(--bd);padding:12px 16px;border-radius:10px;box-shadow:0 8px 30px rgba(0,0,0,.4)}
</style></head><body>
<header><h1>🧪 QA · E2E CRIS</h1>
<div class="health" id="health"><span class="pill"><span class="dot" id="h-fix"></span>fixture</span><span class="pill"><span class="dot" id="h-res"></span><span id="h-res-t">residual</span></span><span class="pill"><span class="dot" id="h-run"></span><span id="h-run-t">último run</span></span></div>
</header>
<nav><button class="on" data-t="run">Ejecutar</button><button data-t="res">Resultados</button><button data-t="fix">Fixture · Limpieza</button></nav>
<main>
<section id="t-run">
  <div class="card"><b>Presets</b><div class="presets" id="presets"></div></div>
  <div class="card"><div class="row" style="margin-bottom:10px"><b style="flex:1">Escenarios</b>
    <input type="text" id="filter" placeholder="filtrar…" oninput="filterCat()">
    <span class="mut" title="El catalogo Python corre en modo live sobre la fixture QA">catalogo real · live</span>
    <span class="mut" id="selcount">0 sel.</span>
    <button class="btn" id="runbtn" onclick="doRun()">▶ Ejecutar</button></div>
    <div id="runstatus" class="mono mut" style="margin-top:10px"></div>
    <div id="catalog">${catHtml}</div></div>
</section>
<section id="t-res" class="hidden">
  <div class="card" id="liverun" style="display:none"><b>Run en vivo</b><div class="progress"><div class="bar" id="livebar"></div></div><div id="livecases" class="mono"></div></div>
  <div class="card"><div class="row" style="justify-content:space-between"><b>Historial de runs</b><button class="btn sec" onclick="loadRuns()">↻</button></div><div id="runstbl">cargando…</div></div>
  <div class="card" id="detailcard" style="display:none"><b>Detalle del run</b><div id="detail"></div></div>
</section>
<section id="t-fix" class="hidden">
  <div class="card"><b>Salud de la fixture</b><div id="fixdetail" class="mono">cargando…</div><div class="row" style="margin-top:10px"><button class="btn sec" onclick="loadHealth()">↻ Revalidar</button></div></div>
  <div class="card"><b>Limpieza de datos QA</b><p class="mut">Borra filas sintéticas del teléfono QA (dry-run primero).</p>
    <div class="row"><button class="btn sec" onclick="doCleanup(true)">Dry-run</button><button class="btn" onclick="doCleanup(false)" style="background:var(--fail)">Ejecutar limpieza real</button></div>
    <div id="cleanout" class="mono" style="margin-top:10px"></div></div>
</section>
</main>
<script>
const TOKEN=${JSON.stringify(token)};
const API='qa-panel-api';
async function api(action,extra){const r=await fetch(API,{method:'POST',headers:{'Content-Type':'application/json','x-ql-sync-token':TOKEN},body:JSON.stringify(Object.assign({action,token:TOKEN},extra||{}))});return r.json();}
function toast(m){const t=document.createElement('div');t.className='toast';t.textContent=m;document.body.appendChild(t);setTimeout(()=>t.remove(),3200);}
// tabs
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>{document.querySelectorAll('nav button').forEach(x=>x.classList.remove('on'));b.classList.add('on');['run','res','fix'].forEach(t=>document.getElementById('t-'+t).classList.toggle('hidden',t!==b.dataset.t));if(b.dataset.t==='res')loadRuns();if(b.dataset.t==='fix')loadHealth();});
// presets
const PRESETS=[['Smoke','5 casos rápidos',['E2E-04','E2E-05','PRC-01','HDF-02','GRD-01']],['Gate de deploy','11 ship-blockers',['E2E-04','E2E-05','E2E-07','PRC-01','PRC-06','HDF-01','GRD-01','LOSS-01','LOSS-02','NEG-03','INF-02']],['Full catálogo','35 escenarios',['*']]];
const pc=document.getElementById('presets');PRESETS.forEach(([n,d,ids])=>{const el=document.createElement('div');el.className='preset';el.innerHTML='<b>'+n+'</b><small>'+d+'</small>';el.onclick=()=>applyPreset(ids);pc.appendChild(el);});
function applyPreset(ids){const all=ids[0]==='*';document.querySelectorAll('.scbox').forEach(c=>c.checked=(all&&c.dataset.manual!=='1')||ids.includes(c.value));syncGroups();updSel();toast(all?'Catálogo no manual seleccionado':ids.length+' escenarios');}
document.querySelectorAll('.gbox').forEach(g=>g.onchange=()=>{g.closest('.grp').querySelectorAll('.scbox').forEach(c=>c.checked=g.checked);updSel();});
document.querySelectorAll('.scbox').forEach(c=>c.onchange=()=>{syncGroups();updSel();});
function syncGroups(){document.querySelectorAll('.grp').forEach(grp=>{const bs=[...grp.querySelectorAll('.scbox')];grp.querySelector('.gbox').checked=bs.every(b=>b.checked);});}
function updSel(){document.getElementById('selcount').textContent=document.querySelectorAll('.scbox:checked').length+' sel.';}
function filterCat(){const q=document.getElementById('filter').value.toLowerCase();document.querySelectorAll('.sc').forEach(l=>{l.style.display=l.textContent.toLowerCase().includes(q)?'':'none';});}
function selectedIds(){return [...document.querySelectorAll('.scbox:checked')].map(c=>c.value);}
function groupsFromIds(ids){const map={E2E:'outbound',BTN:'buttons',PRC:'pricing',LOSS:'loss',HDF:'handoff',MV:'inbound',WIN:'scheduler',LEG:'inbound',NEG:'negative',INF:'labels'};return [...new Set(ids.map(i=>map[i.split('-')[0]]).filter(Boolean))];}
function setRunStatus(m,bad){const el=document.getElementById('runstatus');if(el){el.textContent=m||'';el.style.color=bad?'var(--fail)':'var(--mut)';}}
async function doRun(){const ids=selectedIds();if(!ids.length){setRunStatus('Selecciona al menos un escenario.',true);return toast('Selecciona al menos un escenario');}const manualWarn=ids.includes('OUT-FU-01')?'\\n\\nOUT-FU-01 fuerza CONTACTED_2 y CONTACTED_3; enviará WhatsApp reales al teléfono QA.':'';if(!confirm(ids.length+' escenario(s) del catalogo real contra la fixture QA (live).\\n\\nLos ejecuta n8n (QA-08), un escenario a la vez. Tarda varios minutos; el avance se ve en Resultados.'+manualWarn+'\\n\\nContinuar?')){setRunStatus('Ejecución cancelada.');return;}const btn=document.getElementById('runbtn');btn.disabled=true;btn.textContent='Encolando...';setRunStatus('Encolando '+ids.join(', ')+'...');try{const res=await api('enqueue',{ids});btn.disabled=false;btn.textContent='▶ Ejecutar';if(!res.ok||!res.queued){const msg='Error al encolar: '+(res.error||res.result?.trigger_error||'respuesta no OK');setRunStatus(msg,true);toast(msg);return;}const rk=res.run_key||res.selection?.run_key||'run reciente';setRunStatus('Encolado: '+rk+'. Abriendo Resultados...');toast('Encolado: '+rk);document.querySelector('nav button[data-t=res]').click();setTimeout(loadRuns,1200);}catch(e){btn.disabled=false;btn.textContent='▶ Ejecutar';const msg='Error de red al encolar: '+String(e.message||e).slice(0,180);setRunStatus(msg,true);toast(msg);}}

// results
async function loadRuns(){const el=document.getElementById('runstbl');el.textContent='cargando…';const res=await api('runs',{limit:25});if(!res.ok){el.textContent='error: '+res.error;return;}if(!res.runs.length){el.innerHTML='<p class=mut>Sin runs todavía.</p>';return;}el.innerHTML='<table><thead><tr><th>Fecha</th><th>Modo</th><th>Por</th><th>Estado</th><th>Resumen</th><th></th></tr></thead><tbody>'+res.runs.map(r=>{const s=r.summary||{};const p=s.passed!=null?s.passed+'/'+s.total:'—';const st=r.status||'';const bc=st==='PASSED'||st==='SUCCESS'?'b-ok':st==='RUNNING'?'b-run':st==='FAILED'||st==='ERROR'?'b-fail':'b-mut';return '<tr><td class=mono>'+(r.created_at||'').replace('T',' ').slice(0,16)+'</td><td>'+(r.delivery_mode||'')+'</td><td class=mut>'+(r.created_by||'')+'</td><td><span class="badge '+bc+'">'+st+'</span></td><td class=mono>'+p+'</td><td><button class="btn sec" onclick="loadDetail(\\''+r.id+'\\')">ver</button></td></tr>';}).join('')+'</tbody></table>';}
async function loadDetail(id){const dc=document.getElementById('detailcard');dc.style.display='';document.getElementById('detail').textContent='cargando…';const res=await api('run_detail',{run_id:id});if(!res.ok){document.getElementById('detail').textContent='error';return;}const cs=res.cases||[];document.getElementById('detail').innerHTML='<table><thead><tr><th>Escenario</th><th>Grupo</th><th>Modo</th><th>Estado</th></tr></thead><tbody>'+cs.map(c=>{const bc=c.status==='PASSED'?'b-ok':c.status==='FAILED'?'b-fail':c.status==='RUNNING'?'b-run':'b-mut';return '<tr><td class=mono>'+c.scenario_id+'</td><td class=mut>'+(c.scenario_group||'')+'</td><td>'+(c.delivery_mode||'')+'</td><td><span class="badge '+bc+'">'+(c.status||'')+'</span></td></tr>'+(c.assertions?'<tr><td colspan=4><details><summary class=mut>evidencia</summary><pre>'+esc(JSON.stringify({assertions:c.assertions,actual:c.actual,repro:c.repro_payload,error:c.error},null,2))+'</pre></details></td></tr>':'');}).join('')+'</tbody></table>';dc.scrollIntoView({behavior:'smooth'});}
function esc(s){return String(s).replace(/&/g,'&amp;').replace(/</g,'&lt;');}
// fixture
async function loadHealth(){const res=await api('fixture_health',{});const set=(id,ok,warn)=>{const d=document.getElementById(id);d.className='dot '+(warn?'warn':ok?'ok':'bad');};if(!res.ok){document.getElementById('fixdetail').textContent='error: '+res.error;return;}set('h-fix',res.fixture_ok);set('h-res',res.residual_synthetic===0,res.residual_synthetic>0);set('h-run',res.last_run&&(res.last_run.status==='PASSED'||res.last_run.status==='SUCCESS'));document.getElementById('h-res-t').textContent=res.residual_synthetic+' residual';document.getElementById('h-run-t').textContent=res.last_run?('run '+(res.last_run.status||'')):'sin runs';const fd=document.getElementById('fixdetail');if(fd)fd.innerHTML='<pre>'+esc(JSON.stringify({conversacion_qa:res.qa_conversation,memoria:res.qa_memory,filas_sinteticas_residuales:res.residual_synthetic,ultimo_run:res.last_run},null,2))+'</pre>';}
async function doCleanup(dry){const el=document.getElementById('cleanout');el.textContent='ejecutando…';const extra={dry_run:dry};if(!dry){const c=prompt('Escribe DELETE_QA_CONVERSATIONS para confirmar');if(c!=='DELETE_QA_CONVERSATIONS'){el.textContent='cancelado';return;}extra.confirm=c;}const res=await api('cleanup',extra);el.innerHTML='<pre>'+esc(JSON.stringify(res.result||res,null,2))+'</pre>';loadHealth();}
loadHealth();
</script></body></html>`;

return [{ json: { page_html: html } }];

async function __salesProdHttpRequest(opts) {
  if (opts && String(opts.url || '').includes('/rest/v1/')) {
    opts = {
      ...opts,
      headers: {
        ...(opts.headers || {}),
        'Accept-Profile': 'sales_prod',
        'Content-Profile': 'sales_prod',
      },
    };
  }
  return this.helpers.httpRequest(opts);
}

// QA-06 API router — runs as async Code node (Run Once for All Items).
// Reads via Supabase PostgREST (SRK placeholder, injected live). Runs proxy to QA-02/QA-04.
const SB_URL = 'https://quicklink.spb.aigentss.cloud';
const SRK = '${REDACTED_JWT}';
const SYNC_TOKEN = '0211fb62410106c2d4884f3131fd219390ded7d87a8f46e2';
const N8N_BASE = 'https://quicklink.bkn.aigentss.cloud';
const QA_PHONE_LIKE = 'like.*998299109*';
const H = { apikey: SRK, Authorization: 'Bearer ' + SRK, 'Content-Type': 'application/json' };

const body = ($json.body && typeof $json.body === 'object') ? $json.body : {};
const query = $json.query || {};
const headers = $json.headers || {};
const token = headers['x-ql-sync-token'] || body.token || query.token || '';
const action = String(body.action || query.action || 'fixture_health');

function reply(obj, ok = true) { return [{ json: { ok, action, ...obj } }]; }

if (token !== SYNC_TOKEN) {
  return reply({ error: 'unauthorized' }, false);
}

const helpers = this.helpers;
async function sbGet(path) {
  return await __salesProdHttpRequest.call(this, { method: 'GET', url: SB_URL + '/rest/v1/' + path, headers: H, json: true });
}
async function sbPost(path, payload) {
  return await __salesProdHttpRequest.call(this, { method: 'POST', url: SB_URL + '/rest/v1/' + path,
    headers: { ...H, Prefer: 'return=representation' }, body: payload, json: true });
}
async function proxy(path, payload) {
  return await __salesProdHttpRequest.call(this, {
    method: 'POST', url: N8N_BASE + '/webhook/' + path,
    headers: { 'Content-Type': 'application/json', 'x-ql-sync-token': SYNC_TOKEN }, body: payload, json: true,
  }).catch(e => ({ proxy_error: String(e.message || e).slice(0, 300) }));
}

try {
  if (action === 'fixture_health') {
    const qaConv = await sbGet('conversaciones?telefono=' + QA_PHONE_LIKE + '&select=id,estado,chatwoot_conv_id,quicklink_id&order=updated_at.desc&limit=5');
    const residual = await sbGet('conversaciones?quicklink_id=gte.990000000&telefono=' + QA_PHONE_LIKE + '&select=id');
    const residualLeads = await sbGet('leads_quicklink?quicklink_id=gte.990000000&telefono_1=' + QA_PHONE_LIKE + '&select=id');
    const mem = await sbGet('lead_memory?phone=' + QA_PHONE_LIKE + '&select=conversation_state,conversation_id,chatwoot_conv_id&limit=1');
    const lastRun = await sbGet('cris_test_runs?select=id,run_key,status,delivery_mode,summary,created_by,started_at,finished_at&order=created_at.desc&limit=1');
    const realConv = (qaConv || []).find(c => Number(c.quicklink_id) < 990000000) || (qaConv || [])[0] || null;
    return reply({
      fixture_ok: Boolean(realConv && realConv.chatwoot_conv_id),
      qa_conversation: realConv,
      qa_memory: (mem || [])[0] || null,
      residual_synthetic: (residual || []).length + (residualLeads || []).length,
      last_run: (lastRun || [])[0] || null,
    });
  }

  if (action === 'runs') {
    const limit = Math.min(parseInt(body.limit || query.limit || 25, 10) || 25, 100);
    const runs = await sbGet('cris_test_runs?select=id,run_key,status,delivery_mode,scenario_groups,summary,created_by,started_at,finished_at,created_at&order=created_at.desc&limit=' + limit);
    return reply({ runs: runs || [] });
  }

  if (action === 'run_detail') {
    const runId = body.run_id || query.run_id;
    if (!runId) return reply({ error: 'run_id required' }, false);
    const run = await sbGet('cris_test_runs?id=eq.' + encodeURIComponent(runId) + '&select=*&limit=1');
    const cases = await sbGet('cris_test_cases?run_id=eq.' + encodeURIComponent(runId) + '&select=id,scenario_id,scenario_group,delivery_mode,status,severity,expected,actual,assertions,repro_payload,error,started_at,finished_at&order=created_at.asc');
    return reply({ run: (run || [])[0] || null, cases: cases || [] });
  }

  if (action === 'run') {
    // Proxy to QA-02 orchestrator. Panel passes scenario_groups/mode/windows.
    const payload = {
      delivery_mode: body.mode || 'shadow',
      scenario_groups: Array.isArray(body.scenario_groups) ? body.scenario_groups : undefined,
      windows: Array.isArray(body.windows) ? body.windows : undefined,
      allow_public_messages: body.mode === 'live' || body.mode === 'hybrid' ? true : false,
      cleanup: true,
      leads: Array.isArray(body.leads) ? body.leads : undefined,
      requested_by: 'qa-panel',
    };
    const res = await proxy('cris-qa-run', payload);
    return reply({ started: !res.proxy_error, result: res });
  }

  if (action === 'enqueue') {
    // Dispara QA-08 (catálogo real, n8n-native) sin esperar: una corrida tarda
    // minutos y no cabe en una respuesta HTTP del navegador. El webhook async
    // responde al instante; el avance se ve en la pestaña Resultados.
    // (Antes esto encolaba una fila para un runner Python local; ya no hace
    // falta: todo corre en n8n.)
    const selectionLabel = Array.isArray(body.ids) && body.ids.length ? 'ids' : (body.gate === true ? 'gate' : (body.group || 'all'));
    const payload = { created_by: 'qa-panel', run_key: body.run_key || ('qa-panel-' + selectionLabel + '-' + Date.now()) };
    if (body.gate === true) payload.gate = true;
    else if (Array.isArray(body.ids) && body.ids.length) payload.ids = body.ids;
    else if (body.group) payload.group = String(body.group);
    if (body.cw) payload.cw = Number(body.cw);
    if (body.probe === true) payload.probe = true;
    const res = await __salesProdHttpRequest.call(this, {
      method: 'POST', url: 'http://localhost:5678/webhook/cris-qa-catalog-async',
      headers: { 'Content-Type': 'application/json', 'x-ql-sync-token': SYNC_TOKEN },
      body: payload, json: true, timeout: 15000,
    }).catch(e => ({ trigger_error: String(e.message || e).slice(0, 200) }));
    const ok2 = !(res && res.trigger_error);
    return reply({ queued: ok2, launched: ok2, run_key: payload.run_key, selection: payload, result: res });
  }

  if (action === 'queue') {
    const q = await sbGet('cris_test_runs?status=eq.RUNNING'
      + '&select=id,run_key,status,created_by,input,created_at&order=created_at.desc&limit=10');
    return reply({ queue: q || [] });
  }

  if (action === 'cleanup') {
    const dryRun = body.dry_run !== false;
    const res = await proxy('cris-safe-conversation-cleanup', {
      phone: '0998299109', dry_run: dryRun,
      confirm: dryRun ? undefined : body.confirm, requested_by: 'qa-panel',
    });
    return reply({ dry_run: dryRun, result: res });
  }

  return reply({ error: 'unknown action: ' + action }, false);
} catch (e) {
  return reply({ error: String(e.message || e).slice(0, 400) }, false);
}
